package com.spaceagent.platform.runtime;import com.spaceagent.platform.runtime.domain.*;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;
class SupervisorPolicyDomainTest {static final String H="sha256:"+"a".repeat(64);@Test void shadowNeverExecutesAndKillSwitchForcesDeterministic(){var shadow=new SupervisorPolicy(SupervisorPolicyMode.SHADOW,false,false,H,Instant.EPOCH);assertThat(shadow.executesProvider()).isFalse();assertThat(shadow.recordsShadowComparison()).isTrue();var killed=new SupervisorPolicy(SupervisorPolicyMode.DETERMINISTIC,true,false,H,Instant.EPOCH);assertThat(killed.executesProvider()).isFalse();}@Test void selectedModeRequiresExplicitProviderCandidate(){assertThat(new SupervisorPolicy(SupervisorPolicyMode.OPT_IN,false,true,H,Instant.EPOCH).executesProvider()).isTrue();assertThatThrownBy(()->new SupervisorPolicy(SupervisorPolicyMode.SHADOW,false,true,H,Instant.EPOCH)).isInstanceOf(IllegalArgumentException.class);}}
